package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import java.util.*;import java.io.*;import org.json.*;
public final class Stage49Instrumentation extends Instrumentation{
 void check(boolean b,String s){if(!b)throw new AssertionError(s);}void note(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(0,b);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 BananaEngine.Result run(Context c,Semilla m,String q)throws Exception{return BananaEngine.run(c,q,new ArrayList<String[]>(),"",true,m);}
 @Override public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();AndroidRepair.prefs(c).edit().clear().commit();JavaMethodEditor.prefs(c).edit().clear().commit();JavaMethodEditor.loaded=-1;JavaMethodEditor.restore(c);ModularHub.prefs(c).edit().clear().commit();ModularHub.loaded=-1;ModularHub.restore(c);Semilla model=OwnBrain.load(c);String scene=MobilePlan.snapshot(c);run(c,model,"reescribe el metodo del chat: if (text.equal(\"hola taller\")) return \"Buenas, taller\"\nreturn null;");String previousDraft=JavaMethodEditor.prefs(c).getString("draft","");BananaEngine.Result r=run(c,model,"diagnostica mi ultimo cambio");JSONObject report=new JSONObject(AndroidRepair.prefs(c).getString("report",""));check(!report.getBoolean("success")&&report.getJSONArray("attempts").getJSONObject(0).getString("diagnostic").contains("Java no compiló"),"real ECJ diagnostic recorded on Android");check(previousDraft.equals(JavaMethodEditor.prefs(c).getString("draft",""))&&JavaMethodEditor.active==null,"diagnosis is read-only for editor");r=run(c,model,"repara mi ultimo cambio");check(r.text.contains("reparación comprobada")&&JavaMethodEditor.active==null,"multi-attempt repair prepared without activation");JSONObject pending=new JSONObject(AndroidRepair.prefs(c).getString("pending",""));check(pending.getJSONArray("attempts").length()>=3&&pending.getJSONArray("rules").toString().contains("semicolon")&&pending.getJSONArray("rules").toString().contains("method_name"),"compiler loop applied two observed corrections");check(AndroidRepair.cases(c).length()==0,"proposal never trains verified memory");note("NATIVE_COMPILER_DIAGNOSE_REPAIR_TEST_AND_STAGE_OK");
  run(c,model,"aplica reparacion android");check(run(c,model,"hola taller").text.equals("Buenas, taller")&&AndroidRepair.cases(c).length()==1,"applied verified method changes real conversation and records accepted case");check(scene.equals(MobilePlan.snapshot(c)),"repair preserves projects");String active=JavaMethodEditor.prefs(c).getString("active","");r=run(c,model,"repara metodo del chat: System.exit(0); return null;");check(r.text.contains("Fuera del reparador")&&active.equals(JavaMethodEditor.prefs(c).getString("active",""))&&AndroidRepair.prefs(c).getString("pending","").isEmpty(),"unsafe new job cannot activate earlier proposal");check(run(c,model,"aplica reparacion android").text.contains("No hay"),"failed repair has no stale apply action");note("NATIVE_VERIFIED_CASE_MEMORY_AND_UNSUPPORTED_JOB_GUARD_OK");
  r=run(c,model,"repara metodo del chat: if (message == \"hola taller\") return \"Taller dos\"; return null;");check(r.text.contains("reparación comprobada"),"semantic comparison repair prepared");report=new JSONObject(AndroidRepair.prefs(c).getString("report",""));check(report.getJSONArray("attempts").getJSONObject(0).getBoolean("compiled")&&!report.getJSONArray("attempts").getJSONObject(0).getBoolean("passed"),"runtime tests catch bug that compiles");run(c,model,"aplica reparacion android");check(run(c,model,"hola taller").text.equals("Taller dos")&&AndroidRepair.cases(c).length()==2,"semantic fix activated and learned as accepted case");note("NATIVE_RUNTIME_TEST_DETECTS_STRING_IDENTITY_AND_REPAIRS_OK");
  r=run(c,model,"evalua programador android");check(r.text.contains("4/4")&&active.length()>0,"on-device regression benchmark passes four known fault classes");check(scene.equals(MobilePlan.snapshot(c)),"benchmark preserves projects");r=run(c,model,"busca en el codigo: segundo personaje no aparece");check(r.text.contains("src/com/bananalab/lite/")&&r.text.contains("no diagnóstico confirmado"),"source evidence search grounded in installed files");check(JavaChat.progress.isEmpty()&&JavaChat.owner==null,"progress released");out.putString("stream","PASS STAGE49 Android ECJ diagnostics, compile/test/retry cycle, safe staging, real response activation, accepted-case memory, runtime-only bug, synthetic benchmark, source search and project preservation.\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,out);}}
}
